    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color:
                continue
            # Fill interior of a downward V only when both arms are present
            # as diagonals from this apex.
            for depth in range(1, h-r):
