 "content": "def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        colors = sorted({v for v in row if v != 0})
        for color in colors:
            positions = [c for c, v in enumerate(row) if v == color]
            # Each same-color pair forms a horizontal cross-section of the
            # outlined triangular region; fill the cells between its endpoints.
            for left, right in zip(positions, positions[1:]):
                for c in range(left + 1, right):
                    if grid[r][c] == 0:
                        out[r][c] = 2
    return out
